const ELEMENT_PROP_KEYS = new Set(["theme","unit","label","fromLabel","before","after","shiftDuration","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  unit: "ms",
  label: "p99 latency",
  fromLabel: "from",
  before: 840,
  after: 120,
  shiftDuration: 52,
  accent: "#3B5BFD",
  fontFamily: "Space Grotesk",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type DistributionShiftElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof DistributionShiftBase>;

const DistributionShiftInner = forwardRef<
  HTMLDivElement,
  DistributionShiftElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<DistributionShift>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <DistributionShiftBase
          {...(componentProps as unknown as ComponentProps<typeof DistributionShiftBase>)}
        />
      </div>
    </Sequence>
  );
});

export const DistributionShift = Interactive.withSchema({
  Component: DistributionShiftInner,
  componentName: "<DistributionShift>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
